<script setup>
import { computed, ref, watch } from 'vue'
import { Activity, AlertTriangle, Check, ChevronRight, Gauge, Route, Search, ShieldCheck, SlidersHorizontal, Zap } from 'lucide-vue-next'

const emit = defineEmits(['notify'])
const providers = [
  { id: 'all', label: '全部' }, { id: 'Anthropic', label: 'Anthropic' }, { id: 'OpenAI', label: 'OpenAI' },
  { id: 'Google', label: 'Google' }, { id: '境内', label: '境内' }, { id: '自建', label: '自建' },
]
const models = [
  { id: 'claude-opus-4', provider: 'Anthropic', region: '境外', input: 15, output: 75, quality: 97, latency: 6400, caps: ['tools', 'json', 'stream', 'long', 'vision', 'reasoning', 'output'], score: 74 },
  { id: 'claude-sonnet-4', provider: 'Anthropic', region: '境外', input: 3, output: 15, quality: 92, latency: 2400, caps: ['tools', 'json', 'stream', 'long', 'vision', 'output'], score: 79 },
  { id: 'claude-haiku-3.5', provider: 'Anthropic', region: '境外', input: .8, output: 4, quality: 79, latency: 1100, caps: ['tools', 'json', 'stream', 'vision'], score: 68 },
  { id: 'gpt-4.1', provider: 'OpenAI', region: '境外', input: 2, output: 8, quality: 90, latency: 2100, caps: ['tools', 'json', 'stream', 'long', 'vision', 'output'], score: 78 },
  { id: 'gpt-4.1-mini', provider: 'OpenAI', region: '境外', input: .4, output: 1.6, quality: 76, latency: 900, caps: ['tools', 'json', 'stream', 'vision', 'output'], score: 72 },
  { id: 'o3', provider: 'OpenAI', region: '境外', input: 10, output: 40, quality: 96, latency: 8200, caps: ['tools', 'stream', 'long', 'vision', 'reasoning'], score: 77 },
  { id: 'gemini-2.5-pro', provider: 'Google', region: '境外', input: 1.25, output: 10, quality: 91, latency: 2900, caps: ['tools', 'json', 'stream', 'long', 'vision', 'reasoning', 'output'], score: 78 },
  { id: 'gemini-2.5-flash', provider: 'Google', region: '境外', input: .3, output: 2.5, quality: 78, latency: 800, caps: ['tools', 'json', 'stream', 'long', 'vision', 'output'], score: 66 },
  { id: 'qwen3-max', provider: '阿里云', region: '境内', input: 1.6, output: 6.4, quality: 85, latency: 2200, caps: ['tools', 'json', 'stream', 'long', 'vision', 'output'], score: 71 },
  { id: 'deepseek-v3', provider: 'DeepSeek', region: '境内', input: .28, output: 1.1, quality: 80, latency: 1800, caps: ['tools', 'json', 'stream', 'long'], score: 69 },
  { id: 'llama-3.3-70b', provider: '自建', region: '自建', input: 0, output: 0, quality: 72, latency: 3100, caps: ['tools', 'stream', 'long'], score: 63 },
  { id: 'bge-m3', provider: '自建', region: '自建', input: .02, output: 0, quality: 84, latency: 300, caps: ['embedding'], score: 58 },
  { id: 'gpt-3.5-turbo', provider: 'OpenAI', region: '境外', input: .5, output: 1.5, quality: 61, latency: 1700, caps: ['tools', 'stream'], score: 45, deprecated: true },
]
const tasks = [
  { id: 'code', label: '工具型编码 agent', required: ['tools', 'json', 'output'], local: false, complexity: '多轮工具 + 结构化输出是硬门槛，缺一不可' },
  { id: 'chat', label: '对话 / 问答', required: [], local: false, complexity: '简单请求优先低成本与低延迟' },
  { id: 'reasoning', label: '复杂推理', required: ['reasoning'], local: false, complexity: '需要推理能力，并提高质量权重' },
  { id: 'vision', label: '图片理解', required: ['vision'], local: false, complexity: '视觉输入为硬性能力要求' },
  { id: 'long', label: '长文生成', required: ['long'], local: false, complexity: '长上下文与稳定输出优先' },
  { id: 'embedding', label: '文档向量化', required: ['embedding'], local: true, complexity: '向量任务优先专用嵌入模型与本地处理' },
]
const dimensions = ref([
  { id: 'task', label: '任务类型', detail: '按 agent 类型绑定默认模型', hard: false, on: true },
  { id: 'complexity', label: '复杂度', detail: '简单用便宜、复杂用强模型', hard: false, on: true },
  { id: 'cost', label: '成本', detail: '预算内选最合适', hard: false, on: true },
  { id: 'latency', label: '延迟', detail: '前台快、后台稳', hard: false, on: true },
  { id: 'capability', label: '能力', detail: '工具/长上下文/视觉/JSON，不匹配直接排除', hard: true, on: true },
  { id: 'compliance', label: '合规', detail: '数据不出境、不走第三方', hard: true, on: true },
  { id: 'availability', label: '可用性', detail: '供应商健康与限流', hard: false, on: true },
  { id: 'consistency', label: '一致性', detail: '会话内固定模型，避免风格跳变', hard: false, on: true },
])
const topicNames = ['决策维度', '注册表', '供应商', '路由策略', '失败处理', '成本配额', '能力匹配', '策略权限', '观测调试', '适配层', '自适应', '成熟度']
const topicCopy = [
  ['同一句需求，任务类型不同，硬门槛就不同', '复杂度判定', '决策维度'],
  ['模型注册表统一承载能力、价格、区域与延迟元数据', '13 个候选模型', '注册表字段'],
  ['供应商状态、区域限制和限流策略共同影响可用候选', '供应商健康', '供应商隔离'],
  ['硬约束先过滤，软目标再排序', '主模型 + 故障转移链', '策略优先级'],
  ['超时、限流与 5xx 使用不同的退避和故障转移规则', '重试与熔断', '错误分类'],
  ['按请求预算预估成本，并在任务级配额内选择', '预算与配额', '成本保护'],
  ['能力不匹配直接排除，不允许被低成本权重抵消', '能力闸门', '能力矩阵'],
  ['按任务数据等级约束区域、供应商和工具权限', '区域策略', '策略权限'],
  ['保存每次候选、过滤原因、排序分数和最终选择', '路由事件', '决策回放'],
  ['统一不同供应商的请求格式、流式响应与错误码', '请求适配', '协议归一'],
  ['用线上反馈调整排序参数，变更需受策略边界约束', '反馈闭环', '受控更新'],
  ['用可复现的任务集验证质量、成本和延迟变化', '评估基线', '上线门槛'],
]
const activeProvider = ref('all')
const activeTask = ref('code')
const selectedModelId = ref('claude-sonnet-4')
const activeTopic = ref(0)
const query = ref('')
const sortMode = ref('均衡')
const task = computed(() => tasks.find(item => item.id === activeTask.value) || tasks[0])
const eligibleModels = computed(() => models.filter(model => {
  if (model.deprecated) return false
  if (dimensions.value.find(item => item.id === 'capability')?.on && !task.value.required.every(cap => model.caps.includes(cap))) return false
  if (dimensions.value.find(item => item.id === 'compliance')?.on && task.value.local && model.region !== '境内' && model.region !== '自建') return false
  return true
}).map(model => {
  let score = model.score
  if (dimensions.value.find(item => item.id === 'cost')?.on) score += Math.max(0, 16 - model.input * .8)
  if (dimensions.value.find(item => item.id === 'latency')?.on) score += Math.max(0, 12 - model.latency / 700)
  if (dimensions.value.find(item => item.id === 'complexity')?.on && activeTask.value === 'reasoning') score += model.caps.includes('reasoning') ? 12 : -20
  if (dimensions.value.find(item => item.id === 'availability')?.on && model.id === 'o3') score -= 12
  if (dimensions.value.find(item => item.id === 'consistency')?.on && model.id === selectedModelId.value) score += 5
  return { ...model, score: Math.round(score) }
}).sort((a, b) => sortMode.value === '最低成本' ? a.input - b.input : sortMode.value === '最低延迟' ? a.latency - b.latency : sortMode.value === '最高质量' ? b.quality - a.quality : b.score - a.score))
const visibleModels = computed(() => models.filter(model => {
  const matchesProvider = activeProvider.value === 'all' || (activeProvider.value === '境内' ? model.region === '境内' : activeProvider.value === '自建' ? model.region === '自建' : model.provider === activeProvider.value)
  return matchesProvider && `${model.id} ${model.provider}`.toLowerCase().includes(query.value.toLowerCase())
}))
const selectedModel = computed(() => models.find(model => model.id === selectedModelId.value) || models[1])
const capabilityLabel = computed(() => task.value.required.length
  ? `${task.value.required.filter(cap => selectedModel.value.caps.includes(cap)).length} / ${task.value.required.length} 通过`
  : '无硬性能力要求')
const topicText = computed(() => topicCopy[activeTopic.value])
watch(eligibleModels, list => {
  if (list.length && !list.some(model => model.id === selectedModelId.value)) selectedModelId.value = list[0].id
}, { immediate: true })
function formatPrice(value) { return value === 0 ? '$0' : `$${value}` }
function chooseTask(id) { activeTask.value = id }
</script>

<template>
  <section class="routing-console" aria-label="模型路由控制台">
    <header class="routing-head">
      <div class="routing-brand"><span><Route :size="17" /></span><div><h1>模型路由</h1><small>模型目录 / 服务商 / 策略 / 故障处理 / 成本 / 能力匹配</small></div></div>
      <div class="routing-kpis"><div><span>路由决策 / 分</span><strong>1,284</strong></div><div><span>P95 延迟</span><strong class="kpi-blue">2.4s</strong></div><div><span>每千次成本</span><strong>$21.00</strong></div><div><span>候选模型</span><strong>{{ eligibleModels.length }}</strong></div><div><span>熔断中</span><strong class="kpi-green">0</strong></div></div>
      <p>路由不是「选一个模型」，是带约束的多目标决策</p>
    </header>
    <div class="routing-grid">
      <aside class="model-catalog">
        <div class="provider-filters"><button v-for="provider in providers" :key="provider.id" :class="{ active: activeProvider === provider.id }" @click="activeProvider = provider.id">{{ provider.label }}<small>{{ provider.id === 'all' ? 13 : provider.id === 'Anthropic' ? 3 : provider.id === 'OpenAI' ? 4 : provider.id === 'Google' ? 2 : provider.id === '境内' ? 2 : 2 }}</small></button></div>
        <label class="model-search"><Search :size="13" /><input v-model="query" placeholder="搜索模型或供应商" aria-label="搜索模型" /><kbd>/</kbd></label>
        <div class="model-list"><button v-for="model in visibleModels" :key="model.id" class="model-row" :class="{ selected: selectedModelId === model.id, unavailable: model.deprecated || (dimensions.find(item => item.id === 'capability').on && !task.required.every(cap => model.caps.includes(cap))) }" @click="selectedModelId = model.id">
          <span class="model-led" :class="model.deprecated ? 'off' : eligibleModels.some(item => item.id === model.id) ? 'on' : 'warn'"></span><span class="model-copy"><strong>{{ model.id }}</strong><small>{{ model.provider }} · Q{{ model.quality }} · {{ model.latency < 1000 ? `${model.latency}ms` : `${(model.latency / 1000).toFixed(1)}s` }}</small></span><span class="model-prices">{{ formatPrice(model.input) }} / {{ formatPrice(model.output) }}<small>{{ model.deprecated ? '已弃用' : eligibleModels.some(item => item.id === model.id) ? '可用' : '能力不匹配' }}</small></span>
        </button><p v-if="!visibleModels.length" class="empty-models">没有匹配的模型</p></div>
        <footer class="catalog-footer">共 13 个模型 <span>当前任务可用 <b>{{ eligibleModels.length }}</b></span><small>● 可用　● 波动　● 排除</small></footer>
      </aside>

      <main class="routing-center">
        <nav class="routing-tabs" aria-label="模型路由主题"><button v-for="(name, index) in topicNames" :key="name" :class="{ active: activeTopic === index }" @click="activeTopic = index"><small>{{ String(index + 1).padStart(2, '0') }}</small>{{ name }}</button></nav>
        <div class="routing-scroll">
          <section class="task-selector"><div class="task-chips"><button v-for="item in tasks" :key="item.id" :class="{ active: activeTask === item.id }" @click="chooseTask(item.id)">{{ item.label }}</button></div><p>{{ task.complexity }}</p></section>
          <div class="decision-layout">
            <section class="dimension-panel"><header><h2>{{ topicText[2] }}</h2><small>开关维度观察候选变化</small></header><button v-for="dimension in dimensions" :key="dimension.id" class="dimension-row" @click="dimension.on = !dimension.on"><span class="toggle" :class="{ on: dimension.on }"><i></i></span><strong>{{ dimension.label }}<em v-if="dimension.hard">硬门槛</em></strong><small>{{ dimension.detail }}</small></button><p class="dimension-note"><ShieldCheck :size="14" />{{ dimensions.filter(item => item.on).length }} 个维度生效：{{ models.length }} 个模型中 {{ eligibleModels.length }} 个进入候选。{{ dimensions.find(item => item.id === 'capability').on ? '能力与合规先排除不合格项。' : '已关闭部分约束，候选结果仅供策略演示。' }}</p></section>
            <section class="candidate-panel"><header><h2>候选集 <small>{{ eligibleModels.length }} 个</small></h2><select v-model="sortMode" aria-label="排序策略"><option>均衡</option><option>最低成本</option><option>最低延迟</option><option>最高质量</option></select></header><div class="candidate-list"><button v-for="(model, index) in eligibleModels.slice(0, 6)" :key="model.id" :class="{ chosen: selectedModelId === model.id }" @click="selectedModelId = model.id"><span>{{ index + 1 }}</span><strong>{{ model.id }}</strong><i>{{ model.score }}</i><small>{{ formatPrice(model.input) }}/{{ formatPrice(model.output) }}</small><b><em :style="{ width: `${Math.max(10, model.score)}%` }"></em></b></button></div><div class="excluded-list"><strong>被排除</strong><span v-for="model in models.filter(item => !eligibleModels.some(candidate => candidate.id === item.id) && !item.deprecated).slice(0, 5)" :key="model.id">{{ model.id }} <small>{{ task.required.filter(cap => !model.caps.includes(cap)).join(' / ') || (task.local && model.region === '境外' ? '区域不符合' : '约束不满足') }}</small></span><small v-if="models.filter(item => !eligibleModels.some(candidate => candidate.id === item.id)).length > 5">… 另有 {{ models.filter(item => !eligibleModels.some(candidate => candidate.id === item.id)).length - 5 }} 个</small></div></section>
          </div>
          <section class="complexity-panel"><header><h2>{{ topicText[1] }}</h2><small>决策信号 · 可观测</small></header><div class="complexity-grid"><div><strong>输入长度</strong><span>&lt; 8k tok → 简单；&gt; 64k → 先压缩再选模型</span></div><div><strong>工具轮数</strong><span>预估 ≥ 4 轮 → 需要多轮工具稳定性好的模型</span></div><div><strong>是否要推理</strong><span>有「为什么 / 为什么错」类问题 → 提高推理权重</span></div></div><p><AlertTriangle :size="13" />复杂度要用长度、轮数、检索等可观测信号在请求前判定，不依赖模型自我评估。</p></section>
          <div class="routing-lower"><section><header><h2>本节覆盖</h2><small>与评审标准对应</small></header><p><Check :size="13" />8 个决策维度　<Check :size="13" />维度可开关　<Check :size="13" />候选原因可见</p></section><section><header><h2>三条判断</h2><small>写进设计评审用</small></header><ol><li>能力与合规是硬门槛，必须在排序前排除。</li><li>任务类型决定门槛，同一模型在不同场景可能不合格。</li><li>每个维度都要定义不满足时的处理方式。</li></ol></section></div>
        </div>
      </main>

      <aside class="routing-inspector"><header><strong>本次路由决策</strong><small>{{ task.label }}</small></header><section class="selected-model"><div><span class="status-pill">选中</span><strong>{{ selectedModel.id }}</strong></div><p>{{ selectedModel.provider }} · {{ selectedModel.region }}</p><div class="inspector-data"><span>能力闸门</span><b>{{ capabilityLabel }}</b><span>输入 / 输出价</span><b>{{ formatPrice(selectedModel.input) }} / {{ formatPrice(selectedModel.output) }}</b><span>估算单次</span><b>${{ (selectedModel.input * .004 + selectedModel.output * .001).toFixed(4) }}</b><span>P50 / P95</span><b>{{ Math.round(selectedModel.latency * .46) }} / {{ selectedModel.latency }}ms</b><span>近 7 日成功率</span><b class="green-text">99.6%</b></div></section><section class="inspector-block"><h3>决策依据 <small>{{ eligibleModels.length }} 个候选</small></h3><p>1　规则命中：任务 = {{ task.label }}</p><p>2　能力过滤：{{ models.length }} → {{ eligibleModels.length }} 个候选</p><p>3　排序策略：{{ sortMode }}</p></section><section class="inspector-block failover"><h3>故障转移链</h3><p><b>主</b><span>{{ selectedModel.id }}</span><small>{{ formatPrice(selectedModel.input) }} / {{ formatPrice(selectedModel.output) }}</small></p><p v-for="(model, index) in eligibleModels.filter(item => item.id !== selectedModel.id).slice(0, 2)" :key="model.id"><b>备{{ index + 1 }}</b><span>{{ model.id }}</span><small>{{ formatPrice(model.input) }} / {{ formatPrice(model.output) }}</small></p><p class="no-fallback"><b>无</b><span>503 no_eligible_model</span></p></section><section class="inspector-block route-events"><h3>路由事件 <small>最近 3 条</small><Activity :size="13" /></h3><div><i></i><span><strong>code-agent-07 → {{ selectedModel.id }} · 规则 R2 命中</strong><small>14:22:03</small></span></div><div><i class="event-amber"></i><span><strong>o3 连续 2 次 5xx · 熔断计数 2/3</strong><small>14:21:55</small></span></div><div><i class="event-green"></i><span><strong>haiku-3.5 承接摘要任务 · 成本降低 83%</strong><small>14:21:40</small></span></div></section><button class="routing-help" @click="emit('notify', '模型路由页面使用本地演示数据')"><Gauge :size="14" />路由决策说明<ChevronRight :size="13" /></button></aside>
    </div>
  </section>
</template>

<style scoped>
